    briefing2: 'and mind your fuel — a dead stick landing still counts.',
    start: { x: 0, z: -610, alt: 0, heading: 0, speed: 0, throttle: 0 },
    buildRings() {
      const rand = mulberry32(9001);
      const rings = [];
      let x = 0;
      let z = -200;
      let heading = 0;
      for (let i = 0; i < 8; i++) {
        heading += (rand() - 0.5) * 0.9;
